         // Now: cache_lru_of(new_self.entries) == old_lru.filter(|k| k != victim)

         // Key insight: filter(|k| k != s[0]) == subrange(1, len) for no-dup sequences.
         lemma_filter_first_is_subrange(old_lru);

         // Invariant properties for the new state:
